ssize_t prepare_iovec(struct kiocb *kiocb, int rw, char __user *buf, unsigned long *nr_segs, struct iovec *iovec) {
    size_t count = kiovec->ki_nbytes;

    if (!access_ok(buf, count)) {
        return -EFAULT;
    }

    if (count > SSIZE_MAX) {
        return -EFAULT;
    }

    if (iovec) {
        iovec->iov_base = buf;
        iovec->iov_len = count;
    }

    if (nr_segs) {
        *nr_segs = 1;
    }

    return 0;
}
